import{_ as e,o as n,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Sponsored Lightning Talk: Advancing Infrastructure with Ceph Technology","description":"","frontmatter":{"title":"Sponsored Lightning Talk: Advancing Infrastructure with Ceph Technology","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","Cliso公司","云计算","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Sponsored_Lightning_Talk_-_Advancing_Infrastructure_with_Ceph_Technology.md","filePath":"posts/2023/Sponsored_Lightning_Talk_-_Advancing_Infrastructure_with_Ceph_Technology.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Sponsored_Lightning_Talk_-_Advancing_Infrastructure_with_Ceph_Technology.md"};function i(p,t,a,l,_,g){return n(),o("div",null,[...t[0]||(t[0]=[s("<p>Ceph技术因其无限灵活性、高可扩展性和最优的总拥有成本（TCO）而备受青睐。Cliso公司，作为Ceph技术的坚定支持者，于此次会议中介绍了其战略和未来计划。</p><p>会议中，Dan详细阐述了Ceph的优势与挑战。Ceph的优势在于其无限灵活性、高可扩展性和最优的TCO，支持块、对象和文件存储，并能处理容器，适用于多种云环境。然而，Ceph的使用复杂性仍然是一个问题，目前大部分改进集中在简化安装过程，而日常操作（day two operations）的简化更为重要。</p><p>Cliso公司的介绍与战略包括：</p><ul><li><strong>公司背景</strong>：Cliso成立于2010年，专注于为不同用户提供定制解决方案，包括公有云、私有云、多云环境以及容器化和Kubernetes栈。</li><li><strong>战略方向</strong>： <ul><li><strong>支持与服务</strong>：提供两种类型的支持——低成本的基本支持和面向关键业务的企业支持。同时，提供咨询和开发服务，如性能调试和可扩展架构设计。</li><li><strong>产品开发</strong>：计划推出Cliso Enterprise Storage，这是一个高度优化的Ceph版本，包含自定义的MGR模块和AI Ops类型的辅助工具（codename Klyso Co-pilot），以简化配置和操作。</li></ul></li></ul><p>未来计划与行动包括：</p><ul><li><strong>产品发布</strong>：Cliso将推出一个经过精心筛选的Ceph版本，以避免使用上游版本可能带来的问题。</li><li><strong>市场扩展</strong>：公司正在扩展到北美市场，并继续支持开源社区，成为Ceph基金会的主要成员。</li><li><strong>社区参与</strong>：计划在德国举办活动，并参与组织即将在温哥华举行的Ceph数据会议。</li></ul><p>会议问答环节中，Dan对Ceph版本选择和社区反馈进行了详细解答。建议等待新版本发布至少一个月后再进行升级，以确保稳定性。同时，对Ceph仪表板的改进建议表示欢迎。</p><p>会议最后，Dan强调了Cliso对Ceph技术的热情和对开源社区的承诺，并鼓励大家参与和支持Ceph技术的发展。</p>",8)])])}const C=e(r,[["render",i]]);export{c as __pageData,C as default};
